ST.xhtml:
IF NOT(superState) THEN
    F_TempControlStatus := TempControlStatus.unknown;
ELSIF NOT(isActive) THEN
    F_TempControlStatus := TempControlStatus.idle;
ELSIF isActive AND isWarmingUp THEN
    F_TempControlStatus := TempControlStatus.warming_up;
ELSIF isActive AND ((NOT(isWarmingUp)) AND (NOT(isControlled))) THEN
    F_TempControlStatus := TempControlStatus.unstable;
ELSIF isActive AND ((NOT(isWarmingUp)) AND isControlled) THEN
    F_TempControlStatus := TempControlStatus.controlled;
ELSE
    F_TempControlStatus := TempControlStatus.invalid_model;
END_IF;

stat.enabled := F_EnabledStatus(
    superState := TRUE,
    isEnabled := config_ref.enabled);
stat.health := F_HealthStatus(
    superState := stat.enabled = EnabledStatus.enabled,
    isGood := (NOT((stat.alarm = HiHiLoLoAlarmStatus.hiHi) OR ((stat.alarm = HiHiLoLoAlarmStatus.loLo) OR error))) AND config_ref.enabled,
    hasWarning := (stat.alarm = HiHiLoLoAlarmStatus.hi) OR ((stat.alarm = HiHiLoLoAlarmStatus.lo) OR (NOT(sharedConfig_ref.alarms.enabled))));
proc.initialize( isEnabled := NOT((stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR ((stat.init = InitializationStatus.initialized) OR (stat.init = InitializationStatus.locked)))) );
proc.resetPtp( isEnabled := stat.init = InitializationStatus.initialized );

model.isSimulated := THIS^.isSimulated;
model.actualStatus := THIS^.actualStatus;
model.value := THIS^.value;
model.ptp1 := THIS^.ptp1;
model.ptp2 := THIS^.ptp2;
model.error := THIS^.error;
model.stat := THIS^.stat;
THIS^.proc.initialize._copyToModel_Process( model := model.proc.initialize );
THIS^.proc.resetPtp._copyToModel_Process( model := model.proc.resetPtp );

proc.initialize( isEnabled := NOT((stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR (stat.init = InitializationStatus.initialized))) );
proc.reset( isEnabled := stat.init = InitializationStatus.initialized );
proc.force( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.initialized) );

THIS^.proc.initialize._copyFromModel_Process( model := model.proc.initialize );
THIS^.proc.reset._copyFromModel_Process( model := model.proc.reset );
